let rec lis (xs : List Int) : Int :=
  match xs with
  | [] => 0
  | y :: rest =>
    let rec recLis (xs' : List Int) : Int :=
      match xs' with
      | [] => 0
      | y' :: rest' =>
        if y' < y then recLis (rest')
        else max recLis (rest') (1 + 1)
    recLis rest
