-- Helper function to find the longest strictly increasing subsequence
let rec findLIS (xs : List Int) (tails : List Int) : Int :=
  match xs with
  | [] => 0
  | x :: xs' =>
    let tails' := findLIS xs' (tails |>.map (fun h => h |>.reverse))
    let newTail := (if x < last tails' |>.head else max tails' |>.head)
    let newTails := tails' |>.map (fun h => h |>.reverse)
    if newTail < x then newTails else newTails |>.reverse
    |> (fun h => h |>.reverse)
    |> List.sum (fun h => if h < x then 1 else 0)
    |> List.sum (fun h => if h < x then 1 else 0)
    |> List.sum (fun h => if h < x then 1 else 0)

