let rec recAux (lst : List Int) (prev : Option Int) (currLen : Nat) (maxLen : Nat) : Nat :=
  match lst with
  | [] => max currLen maxLen
  | x :: xs =>
    match prev with
    | none => recAux xs (some x) 1 (max 1 maxLen)
    | some p =>
