let m := a.size
let n := b.size
let dp := Array.mkArray (m + 1) (Array.mkArray (n + 1) 0)
let result := dp.get (m, n)
let subseqA := computeAllSubsequences a
let subseqB := computeAllSubsequences b
let commonLens := (subseqA.filter (fun l => subseqB.contains l)).map (·.length)
let h_exists := ∃ l ∈ commonLens, l = result
let h_bound := ∀ l ∈ commonLens, l ≤ result
exact ⟨h_exists, h_bound⟩

