import Mathlib.Data.Array.Basic
import Mathlib.Data.List.Basic

def intMax (x y : Int) : Int :=
  if x < y then y else x

def computeAllSubsequences (arr : Array Int) : List (List Int) :=
  let rec aux (acc : List Int) (idx : Nat) : List (List Int) :=
    if idx >= arr.size then acc else
      let head := arr.get idx
      let rest := aux acc (idx + 1)
      head :: rest ++ aux (head :: acc) (idx + 1)
  List.reverse (aux [] 0)

