let len := lst.length
if len < 3 then false
else
  let peakIdx := (List.range len).find (fun i => lst.get! i < lst.get! (i + 1) ∧ lst.get! i > lst.get! (i + 1))
  match peakIdx with
  | none => false
  | some p =>
      let increasing = (List.range p).all (fun i => lst.get! i < lst.get! (i + 1))
      let decreasing = (List.range (len - 1 - p)).all (fun i => lst.get! (p + i) > lst.get! (p + i + 1))
      increasing ∧ decreasing

let rec aux (lst : List Int) (prev : Option Int) (currLen : Nat) (maxLen : Nat) : Nat :=
  match lst with
  | [] => maxLen
  | x :: xs =>
    match prev with
    | none => aux xs (some x) 1 (max 1 maxLen)
    | some p =>
      if x > p then aux xs (some x) (currLen + 1) (max (currLen + 1) maxLen)
      else aux xs (some x) 1 (max currLen maxLen)
